Section Glob.
Variable step : node -> Model -> resp -> Model -> list event -> Prop.
Variable Phi : node -> Model -> Prop.

Fixpoint tglob {R} (t : itree node R) (mo : Model) : Prop :=
  match t with
  | Ret _ => True
  | Vis n k => Phi n mo /\ forall rsp mo' evs, step n mo rsp mo' evs -> tglob (k rsp) mo'
  end.

