Arguments STOT {St} step texit_ {A} t mo Post.

Section StotRules.
Context {St : Type}.
Variable step : node -> Model -> resp -> Model -> list event -> Prop.
Variable exit_ : node -> Model -> word -> Model -> Prop.
Local Notation STOT := (STOT step (fun R0 => texit (R:=R0) step exit_)).

