Lemma STOT_seq {A B} (m : M St A) (k : A -> M St B) (s : St) mo (P : B -> St -> Model -> Prop) :
  (exists P1, STOT (m s) mo P1 /\ forall a s' mo', P1 a s' mo' -> STOT (k a s') mo' P) -> STOT (mbind m k s) mo P.
Proof.
