Lemma hsim_bind {A B A' B'} (R : rel) (ma : M Sa A) (mb : M Sb B) (Q1 : A -> B -> rel)
      (ka : A -> M Sa A') (kb : B -> M Sb B') (Q : A' -> B' -> rel) :
  hsim R ma mb Q1 -> (forall a b, hsim (Q1 a b) (ka a) (kb b) Q) ->
