Lemma hsim_pointwise {A B} (R : rel) (ma : M Sa A) (mb : M Sb B) Q :
  (forall sa moa sb mob, R sa moa sb mob ->
     hsim (fun sa' moa' sb' mob' => sa' = sa /\ moa' = moa /\ sb' = sb /\ mob' = mob) ma mb Q) ->
