Lemma rsim_if {A B} (b : bool) (R : rel) (m1 m1' : M S1 A) (m2 m2' : M S2 B) Q :
  (b = true -> rsim R m1 m2 Q) -> (b = false -> rsim R m1' m2' Q) ->
